const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '0' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '1/3' },
      { kind: 'text', payload: '1/2' },
      { kind: 'text', payload: '1/3 < 1/2' }
    ];
  },
  render: function (input, metrics) {
    var vp = input.viewport || {};
    var W = vp.widthDu || 640;
    var H = vp.heightDu || 360;

    var pad = Math.max(44, Math.min(80, W * 0.1));
    var x0 = pad;
    var x1 = W - pad;
    var u = x1 - x0;
    var axisY = Math.round(H * 0.54);

    var fx = function (f) {
      return Math.round((x0 + u * f) * 100) / 100;
    };

    var axisEnd = x1 + 16;
    var axisCmds = visualSdk.polyline([[x0, axisY], [axisEnd, axisY]]);
    var headCmds = visualSdk.polyline([[axisEnd - 9, axisY - 6], [axisEnd, axisY], [axisEnd - 9, axisY + 6]]);

    var tickCmds = [];
    var i, tx, len;
    for (i = 0; i <= 6; i++) {
      tx = fx(i / 6);
      len = (i === 0 || i === 2 || i === 3 || i === 6) ? 9 : 5;
      tickCmds = tickCmds.concat(visualSdk.polyline([[tx, axisY - len], [tx, axisY + len]]));
    }

    var dotA = visualSdk.circle(fx(1 / 3), axisY, 5);
    var dotB = visualSdk.circle(fx(1 / 2), axisY, 5);

    var paths = [
      { id: 'axis', commands: axisCmds },
      { id: 'arrow', commands: headCmds },
      { id: 'ticks', commands: tickCmds },
      { id: 'dotA', commands: dotA },
      { id: 'dotB', commands: dotB }
    ];

    var lowY = Math.min(axisY + 52, H - 60);
    var upperY = Math.max(axisY - 46, 22);
    var capY = Math.min(axisY + 96, H - 20);

    var root = {
      type: 'group',
      children: [
        { type: 'path', pathId: 'axis', stroke: '#26354a', fill: 'none' },
        { type: 'path', pathId: 'arrow', stroke: '#26354a', fill: 'none' },
        { type: 'path', pathId: 'ticks', stroke: '#26354a', fill: 'none' },
        { type: 'path', pathId: 'dotA', stroke: '#1b5e9c', fill: '#1b5e9c' },
        { type: 'path', pathId: 'dotB', stroke: '#1b5e9c', fill: '#1b5e9c' },
        { type: 'label', x: x0, y: axisY + 28, text: '0', fontSize: 16, fill: '#26354a', align: 'center', baseline: 'middle' },
        { type: 'label', x: x1, y: axisY + 28, text: '1', fontSize: 16, fill: '#26354a', align: 'center', baseline: 'middle' },
        { type: 'label', x: fx(1 / 3), y: lowY, text: '1/3', fontSize: 17, fill: '#1b5e9c', align: 'center', baseline: 'middle' },
        { type: 'label', x: fx(1 / 2), y: upperY, text: '1/2', fontSize: 17, fill: '#1b5e9c', align: 'center', baseline: 'middle' },
        { type: 'label', x: W / 2, y: capY, text: '1/3 < 1/2', fontSize: 15, fill: '#2b3a4a', align: 'center', baseline: 'middle' }
      ]
    };

    return {
      schemaVersion: 1,
      sceneId: 'number-line-thirds-halves',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: root
    };
  }
};
